  res.on('end', () => console.log(data));
});

req.on('error', (e) => console.error(e));
req.end();
EOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat > scripts/generate_palette.mjs << 'EOF'
import http from 'http';
import { argv } from 'process';

const args = argv.slice(2);
let model = 'default';
const input = [];
let pretty = false;

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--model' && args[i+1]) {
    model = args[++i];
  } else if (args[i] === '--pretty') {
    pretty = true;
  } else if (args[i] === '--input' && args[i+1]) {
    for (let j = i + 1; j < args.length && !args[j].startsWith('--'); j++) {
      input.push(args[j]);
    }
    i = j - 1;
  }
}

if (input.length === 0) input.push('N', 'N', 'N', 'N', 'N');

const locked = input.map(c => c === 'N' ? null : c);

const postData = JSON.stringify({ model, locked });
const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/api/',
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(postData) }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    const result = JSON.parse(data);
    console.log(JSON.stringify(result));
  });
});

req.on('error', (e) => console.error(e));
req.write(postData);
req.end();
EOF\n",
      "duration": 0.1
    }
